<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Terms Consent</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --card: rgba(255, 255, 255, 0.92);
        --text: #102033;
        --muted: #5b6b7f;
        --border: #d8e0ea;
        --accent: #2563eb;
        --accent-strong: #1d4ed8;
        --focus: rgba(37, 99, 235, 0.2);
        --shadow: 0 20px 60px rgba(16, 32, 51, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
        font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
          sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #ffffff 0, #eef4ff 42%, var(--bg) 100%);
      }

      .card {
        width: min(100%, 460px);
        padding: 32px;
        border: 1px solid rgba(216, 224, 234, 0.9);
        border-radius: 24px;
        background: var(--card);
        box-shadow: var(--shadow);
        backdrop-filter: blur(10px);
      }

      h1 {
        margin: 0 0 8px;
        font-size: clamp(1.5rem, 2.5vw, 2rem);
        line-height: 1.15;
      }

      .lead {
        margin: 0 0 24px;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 20px;
      }

      .form-field {
        display: grid;
        gap: 10px;
        padding: 16px;
        border: 1px solid var(--border);
        border-radius: 18px;
        background: #fff;
      }

      .checkbox-row {
        display: flex;
        gap: 12px;
        align-items: flex-start;
      }

      input[type="checkbox"] {
        margin-top: 4px;
        inline-size: 18px;
        block-size: 18px;
        accent-color: var(--accent);
      }

      label {
        font-weight: 600;
        cursor: pointer;
      }

      .helper {
        margin: 2px 0 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .actions {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 12px 18px;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        box-shadow: 0 12px 24px rgba(37, 99, 235, 0.22);
        cursor: pointer;
        transition: transform 0.15s ease, box-shadow 0.15s ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 16px 28px rgba(37, 99, 235, 0.26);
      }

      button:focus-visible,
      input[type="checkbox"]:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5em;
        color: #0f5132;
        font-weight: 600;
      }

      @media (max-width: 480px) {
        .card {
          padding: 24px;
          border-radius: 20px;
        }

        .actions {
          flex-direction: column;
          align-items: stretch;
        }

        button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main class="card">
      <h1>Agree to the terms</h1>
      <p class="lead">Please review and confirm before continuing.</p>

      <form id="consent-form" novalidate>
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="terms"
              name="terms"
              type="checkbox"
              required
              aria-describedby="terms-help"
            />
            <div>
              <label for="terms">I agree to the Terms of Use</label>
              <p class="helper" id="terms-help">
                Required to proceed with your submission.
              </p>
            </div>
          </div>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
          <div class="status" id="status" role="status" aria-live="polite"></div>
        </div>
      </form>
    </main>

    <script>
      const form = document.getElementById("consent-form");
      const status = document.getElementById("status");

      form.addEventListener("submit", (event) => {
        if (!form.checkValidity()) {
          status.textContent = "";
          return;
        }

        event.preventDefault();
        status.textContent = "Consent saved.";
      });
    </script>
  </body>
</html>
